import type { ComponentType } from "react";
import type { KeepsakeDrawing } from "@/components/adventure/keepsakes/keepsake-drawing.types";
import { CUADERNO_DEL_VIAJERO_KEEPSAKES } from "@/components/adventure/keepsakes/cuaderno-del-viajero-keepsakes.const";
import { CUADERNO_DEL_VIAJERO_PORTRAITS } from "@/components/adventure/portraits/cuaderno-del-viajero-portraits.const";

// The drawn pieces of each adventure's art, by the adventure's slug: the
// portraits of its rivals (by the rival's slug) and the drawings of its
// keepsakes (by the rival's order). Both are generated by
// `npm run adventure:art`; a new adventure is a line in each record, like the
// one in lib/adventure/adventures.ts.

/** Each rival's portrait, by adventure and by rival; each draws inside a 100 x 112 box. */
export const ADVENTURE_PORTRAITS: Readonly<Record<string, Readonly<Record<string, ComponentType>>>> = {
  "cuaderno-del-viajero": CUADERNO_DEL_VIAJERO_PORTRAITS,
};

/** Each keepsake's drawing, by adventure and by the order of the rival that leaves it. */
export const ADVENTURE_KEEPSAKES: Readonly<Record<string, Readonly<Record<number, KeepsakeDrawing>>>> = {
  "cuaderno-del-viajero": CUADERNO_DEL_VIAJERO_KEEPSAKES,
};
